-- Specialised MCQ items (pipeline_supervisor): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('pipeline_supervisor', 'خم‌کاری سرد', 3, 'حداقل شعاع خم سرد صحرایی برای لولهٔ ۲۰ اینچ و بزرگ‌تر طبق ASME B31.8 چقدر است؟', '["۱۰ برابر قطر لوله (10D)","۵ برابر قطر لوله (5D)","۱۸ برابر قطر لوله (18D)","۳۰ برابر قطر لوله (30D)"]'::jsonb, 3, 'SINGLE', null, 'در B31.8 حداقل شعاع خم سرد: NPS ≤ 12: 18D؛ 14: 21D؛ 16: 24D؛ 18: 27D؛ NPS ≥ 20: 30D.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'آزمون هیدرواستاتیک', 2, 'ضریب حداقل فشار آزمون هیدرواستاتیک نسبت به MOP برای Class 2 طبق ASME B31.8 چقدر است؟', '["۱٫۲۵ برابر MOP (آزمون)","۱٫۱ برابر MOP (آزمون)","۱٫۴ برابر MOP (آزمون)","۲٫۰ برابر MOP (آزمون)"]'::jsonb, 0, 'SINGLE', null, 'Class 1 Div 1: ۱٫۱؛ Class 1 Div 2 و Class 2: ۱٫۲۵؛ Class 3 و 4: ۱٫۴.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'آزمون هیدرواستاتیک', 2, 'در آزمون هیدرواستاتیک خط بسته، افزایش دمای آب باعث چه تغییری می‌شود؟', '["کاهش فشار سیستم بسته","افزایش فشار سیستم بسته","تغییر نکردن فشار در همهٔ شرایط","کاهش خودکار حجم آب لوله"]'::jsonb, 1, 'SINGLE', null, 'انبساط آب در حجم ثابت فشار را بالا می‌برد؛ بنابراین دما باید ثبت و فشار تصحیح شود.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'پیگ', 2, 'قطر صفحهٔ ابعاد‌سنج (Gauging plate) پیگ پس از ساخت معمولاً چند درصد قطر داخلی لوله است؟', '["حدود ۵۰٪ قطر داخلی لوله","حدود ۱۰۰٪ قطر داخلی لوله یا بیشتر","حدود ۹۵٪ قطر داخلی لوله","حدود ۷۰٪ قطر داخلی لوله"]'::jsonb, 2, 'SINGLE', null, 'عرف عمومی: صفحهٔ گیج ۹۵٪ کوچک‌ترین قطر داخلی؛ آسیب صفحه نشانهٔ مانع/خمیدگی بیش از حد است.', 'عرف عملیات پیگ‌رانی / IGS'),
  ('pipeline_supervisor', 'ترتیب اجرا', 2, 'کدام ترتیب اجرای صحیح عملیات خط لوله را نشان می‌دهد؟', '["پایین‌گذاری، جوش، NDT، پوشش سرجوش","پوشش سرجوش، جوش، پایین‌گذاری، NDT","NDT، پایین‌گذاری، جوش، هالیدی","جوش، NDT، پوشش سرجوش، هالیدی، پایین‌گذاری"]'::jsonb, 3, 'SINGLE', null, 'جوش پیش از NDT و پوشش؛ هالیدی پیش از پایین‌گذاری تا عیوب پوشش قبل از دفن اصلاح شود.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'HDD', 3, 'حداقل شعاع خمش لولهٔ فولادی در عبور HDD معمولاً چند برابر قطر خارجی در نظر گرفته می‌شود؟', '["حدود ۱۰۰۰ برابر قطر","حدود ۱۰ برابر قطر","حدود ۱۰۰ برابر قطر","حدود ۵۰۰۰ برابر قطر"]'::jsonb, 0, 'SINGLE', null, 'برای جلوگیری از تنش خمشی و آسیب پوشش، شعاع حداقل معمول حدود ۱۰۰۰D (در بعضی طراحی‌ها ۱۲۰۰D) است.', 'ASME B31.8 / PRCI HDD Manual'),
  ('pipeline_supervisor', 'فاصلهٔ ایمنی', 2, 'حداقل فاصلهٔ آزاد خط انتقال با سایر ساختارهای زیرزمینی غیرمرتبط طبق 49 CFR 192.325 چقدر است؟', '["۵۰ میلی‌متر (۲ اینچ)","۳۰۵ میلی‌متر (۱۲ اینچ)","۱۵ میلی‌متر (نیم اینچ)","۱۲۰۰ میلی‌متر (۴۸ اینچ)"]'::jsonb, 1, 'SINGLE', null, 'خط انتقال باید با حداقل ۱۲ in از سایر ساختارهای زیرزمینی فاصله داشته باشد.', '49 CFR 192.325'),
  ('pipeline_supervisor', 'خشک‌کردن خط', 2, 'معیار رایج پذیرش خشک‌کردن (Drying) خط لولهٔ گاز پس از تست هیدرواستاتیک چیست؟', '["نقطهٔ شبنم حدود +۲۰°C یا بیشتر","نقطهٔ شبنم حدود +۵°C یا بیشتر","نقطهٔ شبنم حدود −۲۰°C یا کمتر","دمای هوای محیط حدود −۲°C یا کمتر"]'::jsonb, 2, 'SINGLE', null, 'برای جلوگیری از تشکیل هیدرات و خوردگی، نقطهٔ شبنم گاز/هوای خروجی باید حدود −۲۰°C یا کمتر باشد.', 'IGS / عرف خشک‌کردن خطوط گاز'),
  ('pipeline_supervisor', 'پاکسازی خط', 2, 'قبل از ورود گاز به خط لولهٔ جدید برای جلوگیری از مخلوط قابل انفجار چه می‌شود؟', '["ورود مستقیم گاز با فشار پایین به خط","تخلیهٔ هوا با سرعت زیاد کمپرسور","باز کردن انتهای خط تا بوی گاز برسد","پاکسازی با نیتروژن تا اکسیژن زیر حد ایمن"]'::jsonb, 3, 'SINGLE', null, 'اختلاط هوا و متان در محدودهٔ ۵ تا ۱۵٪ قابل انفجار است؛ فاصلهٔ نیتروژنی مانع تماس مستقیم گاز و هوا می‌شود.', 'API 2200 / IGS – Purging'),
  ('pipeline_supervisor', 'DWTT', 3, 'آزمون DWTT برای لولهٔ API 5L با چه هدفی انجام می‌شود و حداقل سطح پذیرش رایج چقدر است؟', '["سنجش مقاومت در برابر گسترش شکست؛ برش حدود ۸۵٪","سنجش سختی سطح لوله؛ مقدار ۲۲ راکول","سنجش کشش عرضی لوله؛ ۱۰۰٪ SMYS","سنجش ضخامت پوشش لوله؛ ۳ میلی‌متر"]'::jsonb, 0, 'SINGLE', null, 'DWTT شکست نرم/ترد را بررسی می‌کند؛ معیار معمول میانگین سطح برش (Shear area) حداقل ۸۵٪ است.', 'API 5L (PSL2) / API RP 5L3'),
  ('pipeline_supervisor', 'API 5L', 2, 'کدام مورد از الزامات تکمیلی PSL2 نسبت به PSL1 در API 5L است؟', '["آزمون ضربه برای تمام ضخامت‌ها اختیاری است","آزمون ضربه شارپی اجباری و NDT کامل درز","بازرسی چشمی لوله به‌جای آزمایش مکانیکی","حذف آزمون هیدرواستاتیک در کارخانه"]'::jsonb, 1, 'SINGLE', null, 'PSL2 آزمون ضربه (CVN)، حدود شیمیایی سخت‌گیرانه‌تر (CE/Pcm) و NDT ۱۰۰٪ درز را الزام می‌کند.', 'API 5L (PSL2)'),
  ('pipeline_supervisor', 'محاسبه تنش', 2, 'لولهٔ X65 (SMYS=448 MPa) تنش محیطی ۲۸۷٫۵ MPa دارد. تنش محیطی چند درصد SMYS است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"٪","value":64.2,"tolPct":1}'::jsonb, '287.5 / 448 × 100 ≈ 64.2% SMYS', 'ASME B31.8'),
  ('pipeline_supervisor', 'حمل و جابه‌جایی', 1, 'برای بلند کردن لولهٔ پوشش‌دار در کارگاه کدام وسیله مناسب‌تر است؟', '["زنجیر فولادی بی‌حفاظ و سخت","قلاب مستقیم داخل لبهٔ پخ لوله","تسمهٔ پهن یا کرادل پوشش‌دار","کابل فولادی سیمی بی‌پوشش و زبر"]'::jsonb, 2, 'SINGLE', null, 'تماس مستقیم فلز با پوشش یا لبهٔ پخ، پوشش را می‌خراشد یا پخ را آسیب می‌زند؛ تسمهٔ پهن توصیه می‌شود.', 'عرف ایمنی حمل لوله / IGS'),
  ('pipeline_supervisor', 'بستر خط', 2, 'بستر زیر و دور لوله (Padding) در ترانشه چه مشخصه‌ای باید داشته باشد؟', '["شن درشت گوشه‌دار و سنگ‌ریزه تیز","خاک رسی با کلوخ‌های بزرگ و سخت","قطعات بتن و آوار ساختمانی تیز","خاک نرم الک‌شده بی‌سنگ تیز با ضخامت کافی"]'::jsonb, 3, 'SINGLE', null, 'پوشش لوله از ضربهٔ سنگ و اجسام تیز آسیب می‌بیند؛ بستر نرم و یکنواخت تکیه‌گاه و محافظت می‌دهد.', 'IGS-C-PL / ASME B31.8'),
  ('pipeline_supervisor', 'MAOP', 2, 'تعریف MAOP در خط لولهٔ گاز کدام است؟', '["بیشترین فشار مجاز سیستم طبق کد","فشار آزمون هیدرواستاتیک در کارخانه","کمترین فشار لازم برای انتقال گاز","فشار ورودی کمپرسور در حالت عادی"]'::jsonb, 0, 'SINGLE', null, 'MAOP بر اساس طراحی، کلاس موقعیت و نتایج آزمون تعیین می‌شود و بیشتر از آن مجاز نیست.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'علامت‌گذاری مسیر', 1, 'علائم و تابلوهای مسیر خط لوله (Line marker) در کدام نقاط الزامی است؟', '["ایستگاه‌های سرویس و دفتر پیمانکار","تقاطع جاده، راه‌آهن، رودخانه و مناطق مسکونی","داخل ترانشه پس از پایان خاکریزی","روی بدنهٔ لوله در محل کارگاه"]'::jsonb, 1, 'SINGLE', null, 'علائم مسیر برای جلوگیری از آسیب شخص ثالث در محل عبور از موانع و نقاط دسترسی نصب می‌شود.', '49 CFR 192.707'),
  ('pipeline_supervisor', 'اتصال نهایی', 3, 'جوش اتصال نهایی (Golden weld) که در آزمون هیدرواستاتیک شرکت نمی‌کند چگونه کنترل می‌شود؟', '["بازرسی چشمی به‌تنهایی کفایت می‌کند","نمونه‌گیری ۱۰٪ مثل جوش‌های دیگر","۱۰۰٪ NDT (RT و UT) و بازرسی چشمی","تست فشار هوا در ۱ بار برای تأیید"]'::jsonb, 2, 'SINGLE', null, 'چون تست فشار ندارد، جوش اتصال نهایی باید ۱۰۰٪ با روش‌های حجمی کنترل شود.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('pipeline_supervisor', 'عبور از رودخانه', 3, 'عمق دفن لوله در بستر رودخانه عمدتاً بر اساس کدام عامل تعیین می‌شود؟', '["رنگ آب و دمای فصل سال بازدید","قطر پیچ‌های ایستگاه تقلیل فشار","سرعت باد در محل عبور از رودخانه","عمق آبشستگی طراحی و پایداری بستر"]'::jsonb, 3, 'SINGLE', null, 'پایین‌ترین عمق آبشستگی با دورهٔ بازگشت طراحی و عمق دفن کافی برای جلوگیری از بیرون‌زدگی لوله انتخاب می‌شود.', 'ASME B31.8 – عبور از آب'),
  ('pipeline_supervisor', 'ضریب طراحی', 2, 'ضریب طراحی F برای لوله‌کشی ایستگاه‌های تقویت فشار (Compressor station piping) طبق B31.8 چقدر است؟', '["۰٫۵۰ (۵۰٪ SMYS)","۰٫۸۰ (۸۰٪ SMYS)","۰٫۷۲ (۷۲٪ SMYS)","۰٫۴۰ (۴۰٪ SMYS)"]'::jsonb, 0, 'SINGLE', null, 'تنش مجاز در لوله‌کشی ایستگاه‌ها با F = 0.50 در همهٔ کلاس‌ها محدود می‌شود.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
where not exists (select 1 from comp_mcq_questions e where e.job_role = v.job_role and e.stem_fa = v.stem_fa);
